{"command":"python3 -c '
import pty
import subprocess

def run_in_pty():
    master, slave = pty.openpty()
    p = subprocess.Popen(["./executable", "-N", "-n"], stdin=slave, stdout=slave, stderr=slave)
    try:
        p.wait(timeout=2)
    except subprocess.TimeoutExpired:
        p.kill()

    import os
    output = b""
    try:
        while True:
            output += os.read(master, 10240)
    except OSError:
        pass
    print("OUTPUT:", output.decode(errors="ignore"))

run_in_pty()
'"}

